---
-- KEYS[1]: coupon:code:map (Bitmap)
-- KEYS[2]: coupon:code:range (ZSet)
-- ARGV[1]: serialNum
-- ARGV[2]: maxRange (serialNum + 5000)
-- ARGV[3]: userId
--
-- 返回值:
--   1~5: 错误码(见 EXCHANGE_COUPON_ERROR_MSG)
--   >10: 优惠券ID (成功)

-- 1. 防重复兑换检查
if(redis.call('GETBIT', KEYS[1], ARGV[1]) == 1) then
    return "1"
end

-- 2. 反查优惠券ID
local arr = redis.call('ZRANGEBYSCORE', KEYS[2], ARGV[1], ARGV[2], 'LIMIT', 0, 1);
if(#arr == 0) then
    return "2"
end
local cid = arr[1]

-- 3. 查询优惠券缓存
local _k1 = "prs:coupon:" .. cid
if(redis.call('EXISTS', _k1) == 0) then
    return "3"
end

-- 4. 校验有效期 (time[1]=秒, HGET存的issueEndTime=毫秒, 统一转为毫秒比较)
local now = redis.call('time')
local nowMs = tonumber(now[1]) * 1000 + tonumber(now[2]) / 1000
local issueEndTime = tonumber(redis.call('HGET', _k1, 'issueEndTime'))
if(issueEndTime and nowMs > issueEndTime) then
    return "4"
end

-- 5. 校验用户领取限额 (先HGET只读查询, 确认不超限再HINCRBY递增)
local _k2 = "prs:user:coupon:" .. cid
-- userLimit 缺省按 1 处理：nil 与 number 比较会直接让脚本抛错
local userLimit = tonumber(redis.call('HGET', _k1, 'userLimit') or "1")
local curCount = tonumber(redis.call('HGET', _k2, ARGV[3]) or "0")
if(curCount >= userLimit) then
    return "5"
end
redis.call('HINCRBY', _k2, ARGV[3], 1)

-- 6. 校验库存并扣减
if (tonumber(redis.call('HGET', _k1, 'totalNum')) <= 0) then
    redis.call('HINCRBY', _k2, ARGV[3], -1)
    return "6"
end
redis.call('HINCRBY', _k1, "totalNum", -1)

-- 7. 设置Bitmap标记已兑换
redis.call('SETBIT', KEYS[1], ARGV[1], "1")

return cid